package main

import (
	"fmt"

	"golang.org/x/crypto/nacl/box"
)

func to32(buffer []byte) [32]byte {
	var public [32]byte
	copy(public[:], buffer)
	return public
}

func main() {

	A := to32([]byte{16, 44, 122, 53, 10, 77, 214, 164, 220, 19, 151, 64, 250, 13, 191, 5, 61, 6, 88, 138, 89, 1, 190, 18, 119, 176, 132, 39, 227, 233, 73, 35})
	a := to32([]byte{160, 184, 150, 49, 86, 171, 26, 150, 235, 114, 62, 19, 126, 123, 44, 11, 225, 238, 103, 124, 241, 203, 122, 13, 147, 247, 18, 48, 24, 232, 121, 121})

	B := to32([]byte{149, 159, 254, 46, 1, 184, 215, 240, 224, 123, 198, 64, 123, 80, 0, 135, 113, 236, 213, 76, 117, 201, 253, 66, 12, 214, 30, 129, 219, 32, 11, 87})
	b := to32([]byte{19, 30, 255, 99, 200, 249, 241, 57, 246, 28, 248, 18, 143, 230, 19, 102, 60, 194, 104, 10, 96, 5, 33, 37, 241, 157, 163, 58, 223, 97, 192, 204})

	var S [32]byte
	box.Precompute(&S, &A, &b)

	fmt.Println("Shared key, \nA:", A, "\nB:", B, "\na:", a, "\nb:", b, "\nS:", S)
}
